--- a/infra/environments/prod/storage.tf
+++ b/infra/environments/prod/storage.tf
@@ -169,6 +169,25 @@ data "aws_iam_policy_document" "dashboard_tls" {
       values   = ["false"]
     }
   }
+
+  statement {
+    sid    = "AllowCloudFrontRead"
